    //             console.log('dentro de response, ', response.photos[imagem].src.large)
    //         },
    //         error: (err) => {
    //             console.log(err);
    //         }
    //     });
    //     console.log('valor do result, ', result)

    //     return result;
    // }

    public createNewCard(form: FormGroup): Observable<NewCard> {
        const newCard = new NewCard();
        newCard.title = form.value.titulo;
        newCard.description = form.value.descricao;

        // Retorna um Observable que emite o novo cartão com a URL da imagem
        return new Observable(observer => {
            this.sortImages().subscribe(imageUrl => {
                newCard.imageUrl = imageUrl;
                observer.next(newCard);
                observer.complete();
            }, error => {
                observer.error(error);
            });
        });
    }

    private sortImages(): Observable<string> {
        const pagina = this.getRandomNumber(1, 10);
        const imagem = this.getRandomNumber(1, 15);

        // Retorna um Observable que emite a URL da imagem
        return new Observable(observer => {
            this.image.getHappyImagesPexels(pagina).subscribe({
                next: (response: PexelsResponse) => {
                    const imageUrl = response.photos[imagem].src.large;
                    console.log('URL da imagem:', imageUrl);
                    observer.next(imageUrl);
                    observer.complete();
                },
                error: (err) => {
                    console.log('Erro ao obter imagens:', err);
                    observer.error(err);
                }
            });
        });
    }

    public getRandomNumber(min: number, max: number): number {
        return Math.floor(Math.random() * (max - min + 1)) + min;
    }
  }
